import * as React from 'react';
import { getRelativeTime } from '../data/mockSocData';

const severityConfig = {
  critical: { borderColor: 'border-red-500', textColor: 'text-red-500', bgColor: 'bg-red-500' },
  high: { borderColor: 'border-orange-500', textColor: 'text-orange-500', bgColor: 'bg-orange-500' },
  medium: { borderColor: 'border-yellow-500', textColor: 'text-yellow-500', bgColor: 'bg-yellow-500' },
  low: { borderColor: 'border-green-500', textColor: 'text-green-500', bgColor: 'bg-green-500' },
};

export default function RecentActivityFeed({ alerts, maxItems = 8 }) {
  // Show all alerts, scrollable container handles the overflow
  const recentAlerts = alerts;

  return (
    <div className="p-6 h-full flex flex-col border border-white/5 bg-gradient-to-br from-slate-900/90 to-slate-800/70 rounded-3xl backdrop-blur-md transition-all duration-300 shadow-md hover:border-indigo-500/40 hover:shadow-[0_0_20px_rgba(99,102,241,0.2)]">
      <div className="flex-shrink-0 mb-4">
        <h3 className="font-extrabold text-lg tracking-tight text-white mb-1">
          Recent Activity
        </h3>
        <p className="text-slate-400 text-sm">
          Live security alert feed
        </p>
      </div>

      <div className="flex-1 overflow-y-auto min-h-0 pr-4 -mr-1 [&::-webkit-scrollbar]:w-[6px] [&::-webkit-scrollbar-track]:bg-white/5 [&::-webkit-scrollbar-track]:rounded-full [&::-webkit-scrollbar-thumb]:bg-white/10 [&::-webkit-scrollbar-thumb]:rounded-full hover:[&::-webkit-scrollbar-thumb]:bg-white/20">
        {recentAlerts.map((alert, index) => {
          const config = severityConfig[alert.severity] || severityConfig.medium;
          
          return (
            <div
              key={alert.id}
              className={`p-4 mb-3 rounded-xl bg-white/5 border border-white/5 relative overflow-hidden transition-all duration-300 hover:bg-white/10 hover:-translate-y-0.5 group pl-5`}
            >
              {/* Severity Border Indicator */}
              <div className={`absolute left-0 top-0 bottom-0 w-1 ${config.bgColor}`}></div>

              <div className="flex justify-between items-start mb-1">
                <span className={`flex items-center gap-1.5 text-xs font-extrabold uppercase tracking-wide ${config.textColor}`}>
                  <span className={`w-1.5 h-1.5 rounded-full ${config.bgColor}`}></span>
                  {alert.severity}
                </span>
                <span className="text-slate-500 text-xs font-medium">
                  {getRelativeTime(alert.time)}
                </span>
              </div>

              <p className="font-bold text-white mb-1 text-sm leading-snug">
                {alert.title}
              </p>

              <p className="text-slate-400 text-xs flex items-center gap-1">
                {alert.entity}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
}
